11	COMMENT ON COLUMN wind_line.code IS '线路编码，唯一';
12	COMMENT ON COLUMN wind_line.name IS '线路名称';
13	COMMENT ON COLUMN wind_line.status IS '线路状态：NORMAL 正常 / SLOW_STOP 缓停 / EMERGENCY_STOP 紧急停车';
14	COMMENT ON COLUMN wind_line.created_at IS '创建时间（UTC）';
15	
16	CREATE UNIQUE INDEX IF NOT EXISTS uk_wind_line_code ON wind_line (code);
17	
18	CREATE TABLE IF NOT EXISTS wind_station (
19	    id BIGINT AUTO_INCREMENT PRIMARY KEY,
20	    line_id BIGINT NOT NULL,
