22	    name VARCHAR(128) NOT NULL
23	);
24	COMMENT ON TABLE wind_station IS '线路站点（合成数据）';
25	COMMENT ON COLUMN wind_station.line_id IS '所属线路 id';
26	COMMENT ON COLUMN wind_station.seq_no IS '站点顺序号，从 1 开始';
27	COMMENT ON COLUMN wind_station.name IS '站点名称';
28	
29	CREATE UNIQUE INDEX IF NOT EXISTS uk_wind_station_line_seq ON wind_station (line_id, seq_no);
30	
