32	    id BIGINT AUTO_INCREMENT PRIMARY KEY,
33	    line_id BIGINT NOT NULL,
34	    seq_no INT NOT NULL,
35	    from_station_id BIGINT NOT NULL,
36	    to_station_id BIGINT NOT NULL
37	);
38	COMMENT ON TABLE wind_segment IS '线路分段：相邻两站点之间的监测段';
39	COMMENT ON COLUMN wind_segment.line_id IS '所属线路 id';
40	COMMENT ON COLUMN wind_segment.seq_no IS '分段顺序号，从 1 开始';
41	COMMENT ON COLUMN wind_segment.from_station_id IS '起点站 id';
42	COMMENT ON COLUMN wind_segment.to_station_id IS '终点站 id';
43	
44	CREATE UNIQUE INDEX IF NOT EXISTS uk_wind_segment_line_seq ON wind_segment (line_id, seq_no);
45	
46	CREATE TABLE IF NOT EXISTS wind_reading (
47	    id BIGINT AUTO_INCREMENT PRIMARY KEY,
48	    line_id BIGINT NOT NULL,
49	    station_id BIGINT NOT NULL,
50	    measured_at TIMESTAMP(6) NOT NULL,
51	    speed_ms DOUBLE NOT NULL,
52	    late BOOLEAN NOT NULL DEFAULT FALSE,
53	    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
54	);
55	COMMENT ON TABLE wind_reading IS '风速监测数据，按站点与时刻去重';
56	COMMENT ON COLUMN wind_reading.line_id IS '所属线路 id';
57	COMMENT ON COLUMN wind_reading.station_id IS '采集站点 id';
58	COMMENT ON COLUMN wind_reading.measured_at IS '测量时刻（UTC），与站点联合唯一';
59	COMMENT ON COLUMN wind_reading.speed_ms IS '风速，单位 m/s';
60	COMMENT ON COLUMN wind_reading.late IS '是否迟到数据（管制事件归档后到达）：TRUE 只记迟到事件不参与判定';
61	COMMENT ON COLUMN wind_reading.created_at IS '入库时间（UTC）';
62	
63	CREATE UNIQUE INDEX IF NOT EXISTS uk_wind_reading_station_time ON wind_reading (station_id, measured_at);
64	CREATE INDEX IF NOT EXISTS idx_wind_reading_station ON wind_reading (station_id, measured_at);
65	
66	CREATE TABLE IF NOT EXISTS control_event (
67	    id BIGINT AUTO_INCREMENT PRIMARY KEY,
68	    line_id BIGINT NOT NULL,
69	    type VARCHAR(32) NOT NULL,
70	    status VARCHAR(32) NOT NULL,
71	    trigger_segment_id BIGINT,
72	    avg_speed DOUBLE,
73	    triggered_at TIMESTAMP(6) NOT NULL,
74	    archived_at TIMESTAMP(6),
75	    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
76	);
77	COMMENT ON TABLE control_event IS '管制事件，同线路同时刻只允许一个进行中事件，归档为终态';
78	COMMENT ON COLUMN control_event.line_id IS '所属线路 id';
79	COMMENT ON COLUMN control_event.type IS '事件类型：SLOW_STOP 缓停 / EMERGENCY_STOP 紧急停车';
80	COMMENT ON COLUMN control_event.status IS '事件状态：ACTIVE 进行中 / REOPEN_REQUESTED 已申请复开 / RESUMED 已复开（归档终态）';
81	COMMENT ON COLUMN control_event.trigger_segment_id IS '触发分段 id';
82	COMMENT ON COLUMN control_event.avg_speed IS '触发时 10 分钟平均风速，单位 m/s';
83	COMMENT ON COLUMN control_event.triggered_at IS '触发判定对应的测量时刻（UTC）';
