85	
86	CREATE INDEX IF NOT EXISTS idx_control_event_line ON control_event (line_id, status);
87	
88	CREATE TABLE IF NOT EXISTS cabin_release (
89	    id BIGINT AUTO_INCREMENT PRIMARY KEY,
90	    event_id BIGINT NOT NULL,
91	    segment_id BIGINT NOT NULL,
92	    operator_id VARCHAR(64) NOT NULL,
93	    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
94	);
95	COMMENT ON TABLE cabin_release IS '缓停期间在途吊厢按站点逐段放行记录';
96	COMMENT ON COLUMN cabin_release.event_id IS '管制事件 id';
97	COMMENT ON COLUMN cabin_release.segment_id IS '放行分段 id，同一事件内唯一';
98	COMMENT ON COLUMN cabin_release.operator_id IS '操作人标识';
99	COMMENT ON COLUMN cabin_release.created_at IS '放行时间（UTC）';
100	
101	CREATE UNIQUE INDEX IF NOT EXISTS uk_cabin_release_event_segment ON cabin_release (event_id, segment_id);
102	
103	CREATE TABLE IF NOT EXISTS segment_clearance (
104	    id BIGINT AUTO_INCREMENT PRIMARY KEY,
105	    event_id BIGINT NOT NULL,
106	    segment_id BIGINT NOT NULL,
107	    confirmer_id VARCHAR(64) NOT NULL,
108	    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
109	);
110	COMMENT ON TABLE segment_clearance IS '紧急停车救援分段清空确认，须双人确认方可生效';
111	COMMENT ON COLUMN segment_clearance.event_id IS '管制事件 id';
112	COMMENT ON COLUMN segment_clearance.segment_id IS '分段 id';
113	COMMENT ON COLUMN segment_clearance.confirmer_id IS '确认人标识，同一分段同一确认人仅记一次';
114	COMMENT ON COLUMN segment_clearance.created_at IS '确认时间（UTC）';
115	
116	CREATE UNIQUE INDEX IF NOT EXISTS uk_segment_clearance ON segment_clearance (event_id, segment_id, confirmer_id);
117	
118	CREATE TABLE IF NOT EXISTS reopen_confirmation (
119	    id BIGINT AUTO_INCREMENT PRIMARY KEY,
120	    event_id BIGINT NOT NULL,
121	    role VARCHAR(32) NOT NULL,
122	    operator_id VARCHAR(64) NOT NULL,
123	    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
124	);
125	COMMENT ON TABLE reopen_confirmation IS '复开双岗确认记录，运营与机务各确认一次方可复开';
126	COMMENT ON COLUMN reopen_confirmation.event_id IS '管制事件 id';
127	COMMENT ON COLUMN reopen_confirmation.role IS '确认岗位：OPERATIONS 运营 / MAINTENANCE 机务，同一事件每岗位仅一次';
128	COMMENT ON COLUMN reopen_confirmation.operator_id IS '确认人标识';
129	COMMENT ON COLUMN reopen_confirmation.created_at IS '确认时间（UTC）';
130	
131	CREATE UNIQUE INDEX IF NOT EXISTS uk_reopen_confirmation_event_role ON reopen_confirmation (event_id, role);
132	
133	CREATE TABLE IF NOT EXISTS boarding (
134	    id BIGINT AUTO_INCREMENT PRIMARY KEY,
135	    line_id BIGINT NOT NULL,
136	    request_id VARCHAR(64) NOT NULL,
137	    passenger_count INT NOT NULL,
138	    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
139	);
140	COMMENT ON TABLE boarding IS '上客记录，管制期间禁止上客';
141	COMMENT ON COLUMN boarding.line_id IS '线路 id';
142	COMMENT ON COLUMN boarding.request_id IS '幂等请求标识';
143	COMMENT ON COLUMN boarding.passenger_count IS '上客人数';
144	COMMENT ON COLUMN boarding.created_at IS '记录时间（UTC）';
145	
146	CREATE UNIQUE INDEX IF NOT EXISTS uk_boarding_request ON boarding (request_id);
147	
148	CREATE TABLE IF NOT EXISTS late_data_event (
149	    id BIGINT AUTO_INCREMENT PRIMARY KEY,
150	    line_id BIGINT NOT NULL,
151	    station_id BIGINT NOT NULL,
152	    measured_at TIMESTAMP(6) NOT NULL,
153	    speed_ms DOUBLE NOT NULL,
154	    reason VARCHAR(256) NOT NULL,
155	    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
156	);
157	COMMENT ON TABLE late_data_event IS '迟到风速数据事件，管制事件归档后到达的数据只记录不判定';
158	COMMENT ON COLUMN late_data_event.line_id IS '线路 id';
159	COMMENT ON COLUMN late_data_event.station_id IS '站点 id';
160	COMMENT ON COLUMN late_data_event.measured_at IS '测量时刻（UTC）';
161	COMMENT ON COLUMN late_data_event.speed_ms IS '风速，单位 m/s';
162	COMMENT ON COLUMN late_data_event.reason IS '迟到原因说明';
163	COMMENT ON COLUMN late_data_event.created_at IS '记录时间（UTC）';
164	
165	CREATE TABLE IF NOT EXISTS idempotency_record (
166	    request_id VARCHAR(64) PRIMARY KEY,
167	    endpoint VARCHAR(128) NOT NULL,
168	    fingerprint VARCHAR(128) NOT NULL,
169	    response_status INT,
170	    response_body CLOB,
171	    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
172	    completed_at TIMESTAMP
173	);
174	COMMENT ON TABLE idempotency_record IS '写操作幂等记录，指纹覆盖 requestId 与全部业务字段';
175	COMMENT ON COLUMN idempotency_record.request_id IS '幂等请求标识，主键';
176	COMMENT ON COLUMN idempotency_record.endpoint IS '接口标识';
177	COMMENT ON COLUMN idempotency_record.fingerprint IS '请求指纹：requestId 与全部业务字段的 SHA-256';
178	COMMENT ON COLUMN idempotency_record.response_status IS '首次响应 HTTP 状态码，NULL 表示处理中';
179	COMMENT ON COLUMN idempotency_record.response_body IS '首次响应报文，同键同参原样返回';
180	COMMENT ON COLUMN idempotency_record.created_at IS '记录创建时间（UTC）';
181	COMMENT ON COLUMN idempotency_record.completed_at IS '记录完成时间（UTC），NULL 表示处理中';
