1	package com.example.starter.service;
2	
3	import com.example.starter.model.ControlEvent;
4	import com.example.starter.model.ControlEventStatus;
5	import com.example.starter.model.ControlEventType;
6	import com.example.starter.model.LineStatus;
7	import com.example.starter.model.ReopenRole;
8	import com.example.starter.model.WindLine;
9	import com.example.starter.model.WindSegment;
10	import com.example.starter.model.WindStation;
11	import com.example.starter.repo.BoardingRepository;
12	import com.example.starter.repo.ConfirmationRepository;
13	import com.example.starter.repo.ControlEventRepository;
14	import com.example.starter.repo.LineRepository;
15	import com.example.starter.repo.SegmentRepository;
16	import com.example.starter.repo.StationRepository;
17	import com.example.starter.repo.WindReadingRepository;
18	import com.example.starter.web.dto.BoardingRequest;
19	import com.example.starter.web.dto.BoardingResponse;
20	import com.example.starter.web.dto.CabinReleaseRequest;
21	import com.example.starter.web.dto.CabinReleaseResponse;
22	import com.example.starter.web.dto.ClearanceRequest;
23	import com.example.starter.web.dto.ClearanceResponse;
24	import com.example.starter.web.dto.EventView;
25	import com.example.starter.web.dto.LineView;
26	import com.example.starter.web.dto.ReopenApplicationRequest;
27	import com.example.starter.web.dto.ReopenApplicationResponse;
28	import com.example.starter.web.dto.ReopenConfirmationRequest;
29	import com.example.starter.web.dto.ReopenConfirmationResponse;
30	import org.springframework.http.ResponseEntity;
31	import org.springframework.stereotype.Service;
32	
33	import java.time.Duration;
34	import java.time.Instant;
35	import java.util.List;
36	
37	/**
38	 * 管制事件业务：缓停禁止上客与逐段放行、紧急停车救援双人确认、复开申请与双岗确认。
39	 */
40	@Service
41	public class ControlEventService {
42	
43	    /** 复开判定窗口：风速回落至 15m/s 以下并持续 15 分钟，恰满即可申请 */
44	    static final Duration RECOVERY_WINDOW = Duration.ofMinutes(15);
45	    /** 复开风速阈值（m/s），须严格低于该值 */
46	    static final double RECOVERY_THRESHOLD_MS = 15.0;
47	
48	    private final LineRepository lineRepository;
49	    private final StationRepository stationRepository;
50	    private final SegmentRepository segmentRepository;
51	    private final WindReadingRepository readingRepository;
52	    private final ControlEventRepository eventRepository;
53	    private final ConfirmationRepository confirmationRepository;
54	    private final BoardingRepository boardingRepository;
55	    private final IdempotencyService idempotencyService;
56	    private final JsonSupport json;
57	
58	    public ControlEventService(LineRepository lineRepository, StationRepository stationRepository,
59	                               SegmentRepository segmentRepository, WindReadingRepository readingRepository,
60	                               ControlEventRepository eventRepository,
61	                               ConfirmationRepository confirmationRepository,
62	                               BoardingRepository boardingRepository,
63	                               IdempotencyService idempotencyService, JsonSupport json) {
64	        this.lineRepository = lineRepository;
65	        this.stationRepository = stationRepository;
66	        this.segmentRepository = segmentRepository;
67	        this.readingRepository = readingRepository;
68	        this.eventRepository = eventRepository;
69	        this.confirmationRepository = confirmationRepository;
70	        this.boardingRepository = boardingRepository;
71	        this.idempotencyService = idempotencyService;
72	        this.json = json;
73	    }
74	
75	    /**
76	     * 上客：管制期间（缓停/紧急停车）禁止上客。
77	     */
78	    public ResponseEntity<String> board(long lineId, BoardingRequest request) {
79	        String fingerprint = IdempotencyService.fingerprint(
80	                request.requestId(), "boarding", String.valueOf(lineId),
81	                String.valueOf(request.passengerCount()));
82	        return idempotencyService.execute("boarding", request.requestId(), fingerprint, () -> {
83	            WindLine line = lineRepository.findByIdForUpdate(lineId)
84	                    .orElseThrow(() -> ApiException.notFound("线路不存在: " + lineId));
85	            if (line.status() != LineStatus.NORMAL) {
86	                throw ApiException.conflict("线路管制中禁止上客: " + line.status());
87	            }
88	            long boardingId = boardingRepository.insert(lineId, request.requestId(), request.passengerCount());
89	            return json.ok(new BoardingResponse(boardingId, lineId, true));
90	        });
91	    }
92	
93	    /**
94	     * 缓停在途吊厢按站点逐段放行，同一事件同一分段只放行一次。
95	     */
96	    public ResponseEntity<String> releaseCabins(long eventId, long segmentId, CabinReleaseRequest request) {
97	        String fingerprint = IdempotencyService.fingerprint(
98	                request.requestId(), "cabin-release", String.valueOf(eventId),
99	                String.valueOf(segmentId), request.operatorId());
100	        return idempotencyService.execute("cabin-release", request.requestId(), fingerprint, () -> {
101	            ControlEvent event = requireEvent(eventId);
102	            if (event.type() != ControlEventType.SLOW_STOP) {
103	                throw ApiException.unprocessable("仅缓停事件支持吊厢逐段放行");
104	            }
105	            if (event.status() == ControlEventStatus.RESUMED) {
106	                throw ApiException.conflict("管制事件已归档，禁止放行操作");
107	            }
108	            requireSegment(event, segmentId);
109	            boolean inserted = confirmationRepository.insertCabinRelease(eventId, segmentId, request.operatorId());
110	            Instant releasedAt = confirmationRepository.findCabinReleaseAt(eventId, segmentId);
111	            return json.ok(new CabinReleaseResponse(eventId, segmentId, inserted || releasedAt != null, releasedAt));
112	        });
113	    }
114	
115	    /**
116	     * 紧急停车救援分段清空确认：须双人确认，单人确认（含同一人重复确认）不生效。
117	     */
118	    public ResponseEntity<String> confirmClearance(long eventId, long segmentId, ClearanceRequest request) {
119	        String fingerprint = IdempotencyService.fingerprint(
120	                request.requestId(), "clearance", String.valueOf(eventId),
121	                String.valueOf(segmentId), request.confirmerId());
122	        return idempotencyService.execute("clearance", request.requestId(), fingerprint, () -> {
123	            ControlEvent event = requireEvent(eventId);
124	            if (event.type() != ControlEventType.EMERGENCY_STOP) {
125	                throw ApiException.unprocessable("仅紧急停车事件需要救援清空确认");
126	            }
127	            if (event.status() != ControlEventStatus.ACTIVE) {
128	                throw ApiException.conflict("事件当前状态不允许清空确认: " + event.status());
129	            }
130	            requireSegment(event, segmentId);
131	            confirmationRepository.insertClearance(eventId, segmentId, request.confirmerId());
132	            List<String> confirmers = confirmationRepository.listConfirmers(eventId, segmentId);
133	            return json.ok(new ClearanceResponse(eventId, segmentId, confirmers.size(),
134	                    confirmers.size() >= 2, confirmers));
135	        });
136	    }
137	
138	    /**
139	     * 复开申请：风速回落至 15m/s 以下并持续 15 分钟（恰满即可）；
140	     * 紧急停车事件还须全部分段双人确认清空。
141	     */
142	    public ResponseEntity<String> applyReopen(long eventId, ReopenApplicationRequest request) {
143	        String fingerprint = IdempotencyService.fingerprint(
144	                request.requestId(), "reopen-application", String.valueOf(eventId),
145	                request.requestedAt().toString());
146	        return idempotencyService.execute("reopen-application", request.requestId(), fingerprint, () -> {
147	            ControlEvent event = eventRepository.findByIdForUpdate(eventId)
148	                    .orElseThrow(() -> ApiException.notFound("管制事件不存在: " + eventId));
149	            if (event.status() != ControlEventStatus.ACTIVE) {
150	                throw ApiException.conflict("事件当前状态不允许申请复开: " + event.status());
151	            }
152	            List<WindSegment> segments = segmentRepository.findByLineId(event.lineId());
153	            if (event.type() == ControlEventType.EMERGENCY_STOP
154	                    && confirmationRepository.countClearedSegments(eventId) < segments.size()) {
155	                throw ApiException.unprocessable("救援分段尚未全部双人确认清空");
156	            }
157	            Instant requestedAt = request.requestedAt();
158	            Instant windowStart = requestedAt.minus(RECOVERY_WINDOW);
159	            for (WindStation station : stationRepository.findByLineId(event.lineId())) {
160	                Instant min = readingRepository.minMeasuredAtInWindow(station.id(), windowStart, requestedAt);
161	                if (min == null || min.isAfter(windowStart)) {
162	                    throw ApiException.unprocessable("风速回落持续时长未恰满 15 分钟");
163	                }
164	                if (readingRepository.countAtOrAbove(station.id(), windowStart, requestedAt,
165	                        RECOVERY_THRESHOLD_MS) > 0) {
166	                    throw ApiException.unprocessable("风速未回落至 15m/s 以下");
167	                }
168	            }
169	            eventRepository.updateStatus(eventId, ControlEventStatus.REOPEN_REQUESTED);
170	            return json.ok(new ReopenApplicationResponse(eventId, ControlEventStatus.REOPEN_REQUESTED.name()));
171	        });
172	    }
173	
174	    /**
175	     * 复开双岗确认：运营与机务各确认一次后事件归档复开，线路恢复运行。
176	     */
177	    public ResponseEntity<String> confirmReopen(long eventId, ReopenConfirmationRequest request) {
178	        String fingerprint = IdempotencyService.fingerprint(
179	                request.requestId(), "reopen-confirmation", String.valueOf(eventId),
180	                request.role().name(), request.operatorId());
181	        return idempotencyService.execute("reopen-confirmation", request.requestId(), fingerprint, () -> {
182	            ControlEvent event = eventRepository.findByIdForUpdate(eventId)
183	                    .orElseThrow(() -> ApiException.notFound("管制事件不存在: " + eventId));
184	            if (event.status() != ControlEventStatus.REOPEN_REQUESTED) {
185	                throw ApiException.conflict("事件当前状态不允许复开确认: " + event.status());
186	            }
187	            confirmationRepository.insertReopenConfirmation(eventId, request.role().name(), request.operatorId());
188	            List<String> roles = confirmationRepository.listReopenRoles(eventId);
189	            boolean operations = roles.contains(ReopenRole.OPERATIONS.name());
190	            boolean maintenance = roles.contains(ReopenRole.MAINTENANCE.name());
191	            ControlEventStatus status = ControlEventStatus.REOPEN_REQUESTED;
192	            if (operations && maintenance) {
193	                eventRepository.archive(eventId, Instant.now());
194	                lineRepository.updateStatus(event.lineId(), LineStatus.NORMAL);
195	                status = ControlEventStatus.RESUMED;
196	            }
197	            return json.ok(new ReopenConfirmationResponse(eventId, status.name(),
198	                    operations, maintenance, status == ControlEventStatus.RESUMED));
199	        });
200	    }
201	
202	    /**
203	     * 查询线路视图（含进行中事件 id）。
204	     */
205	    public LineView lineView(long lineId) {
206	        WindLine line = lineRepository.findById(lineId)
207	                .orElseThrow(() -> ApiException.notFound("线路不存在: " + lineId));
208	        Long activeEventId = eventRepository.findInProgressByLine(lineId)
209	                .map(ControlEvent::id).orElse(null);
210	        return new LineView(line.id(), line.code(), line.name(), line.status().name(), activeEventId);
211	    }
212	
213	    /**
214	     * 查询管制事件视图（含救援清空进度与复开岗位确认情况）。
215	     */
216	    public EventView eventView(long eventId) {
217	        ControlEvent event = eventRepository.findById(eventId)
218	                .orElseThrow(() -> ApiException.notFound("管制事件不存在: " + eventId));
219	        int totalSegments = segmentRepository.findByLineId(event.lineId()).size();
220	        int clearedSegments = confirmationRepository.countClearedSegments(eventId);
221	        List<String> roles = confirmationRepository.listReopenRoles(eventId);
222	        return new EventView(event.id(), event.lineId(), event.type().name(), event.status().name(),
223	                event.triggerSegmentId(), event.avgSpeed(), event.triggeredAt(), event.archivedAt(),
