package com.example.starter.web.dto;

/**
 * 线路视图。
 *
 * @param id            线路 id
 * @param code          线路编码
 * @param name          线路名称
 * @param status        线路状态
 * @param activeEventId 进行中管制事件 id，无为 null
 */
public record LineView(long id, String code, String name, String status, Long activeEventId) {
}

package com.example.starter.web.dto;

import java.time.Instant;
import java.util.List;

/**
 * 管制事件视图。
 *
 * @param id               事件 id
 * @param lineId           线路 id
 * @param type             事件类型
 * @param status           事件状态
 * @param triggerSegmentId 触发分段 id
 * @param avgSpeed         触发时 10 分钟平均风速（m/s）
 * @param triggeredAt      触发时刻（UTC）
 * @param archivedAt       归档时间（UTC），未归档为 null
 * @param clearedSegments  已双人确认清空的分段数
 * @param totalSegments    线路分段总数
 * @param reopenRoles      已确认的复开岗位
 */
public record EventView(long id, long lineId, String type, String status, Long triggerSegmentId,
                        Double avgSpeed, Instant triggeredAt, Instant archivedAt,
                        int clearedSegments, int totalSegments, List<String> reopenRoles) {
}

package com.example.starter.web.dto;

import jakarta.validation.constraints.NotBlank;

/**
 * 救援分段清空确认请求。
 *
 * @param requestId   幂等请求标识
 * @param confirmerId 确认人标识
 */
public record ClearanceRequest(
        @NotBlank String requestId,
        @NotBlank String confirmerId) {
}

package com.example.starter.model;

/**
 * 管制事件状态。
 */
public enum ControlEventStatus {
    /** 进行中（含救援流程） */
    ACTIVE,
    /** 已申请复开，等待双岗确认 */
    REOPEN_REQUESTED,
    /** 已复开，归档终态 */
    RESUMED
}

